# -*- coding: utf-8 -*-
"""번역 데이터 — DIARY.MSG (러스티의 일기, 서사 요약 60개)."""

DIARY = {
    '4273a42998': '　이 나라의 왕녀 뮤와\n는, 어릴 적부터 아는\n사이인데, 그녀는 만날\n때마다 예뻐지는 것\n같다\n　그런데 성격은 여전히\n짓궂다 다른 사람에게는,\n그런대로 대하면서,\n어째서 나에게만 그녀는\n짓궂게 구는 걸까 여자\n마음은 모르겠구나',
    'b2f305857f': '　내 이름은 러스티　퀸즈랜드의 왕자로, 드라군 왕국의 왕녀 뮤와는 소꿉친구다\n　드라군 왕가는, 용기사의 수장이기도 하며, 우리 리그로드 대륙 주민들에겐 든든한 존재다\n　나는 전투훈련을 받기 위해, 드라군을 방문 중이었는데,',
    'bd1f9080cd': '그때 갑자기 공격을 가해 온 것은 카달이라는 들어본 적 없는 나라의 군대와, 그것을 이끄는 갈자드라는 남자였다 갑작스런 공격에 드라군 왕은, 뮤에게 야마타이의 이가로 가라고 명하며, 성을 탈출시켰다\n　이렇게, 나와 뮤의 여정은 싸움과 함께 막을 올렸다・',
    '39005becb2': '　우리는 우선 자루마로 향했다 자루마 사람들은,\n드라군에게 일어난 일을 모르는 눈치다 우리는, 사람들에게 진실을 알려 공황이 일어나는 것을 두려워해, 드라군이 카달을 자칭하는 군대와 갈자드에 의해 제압당한 것을 말할 수 없었다',
    '7a13c92928': '　뮤는, 거짓말을 하는 것이 괴로운지, 사람들의 전적인 신뢰가 담긴 미소와 따뜻한 말에서, 얼굴을 돌리고 있었다\n나도 마을 사람들을 배신하는 것 같아 몹시 괴로웠다\n　다시 이 마을에 돌아왔을 때, 마을 사람들에게, 어떤 얼굴을 해야 할까・',
    '3302262620': '　새로운 동료가 늘었다 그의 이름은 아스카 이가 최강의 시노비 집단 월조의 두령으로 인술의 달인이다\n　아스카는, 그 전투능력의 높음을 카달에게 인정받아, 협력하라는 명령을 받았다 하지만, 그는 따르지 않아, 카달은, 아스카의 부하들을 붙잡아 닌자 저택에 가두',
    '2cb1aff125': '었다\n　그와 동시에, 이가 사람들에게 아스카가 배신자인 것처럼 오해하게 만들어, 아스카를 고립시켰다\n　하지만, 우리의 협력으로 닌자 저택을 공략해, 아스카의 부하들을 되찾음으로써 이가 사람들의 오해를 풀 수 있었다',
    '1b5de4d2ee': '　야마타이 최대의 도시, 고조 그곳에서 우리는 함정에 빠져, 호쇼인이라는 곳에 갇혔다\n　우리를 도와준 것은, 여도적 시라나미 그녀는, 아무래도 아스카의 소꿉친구였던 모양이다 시라나미는 이제 고조를 어지럽히는 대도적이',
    '64350e2def': '되어 있다 게다가, 훔치는 상대는 악인이고, 훔친 금품을 가난한 사람들에게 나눠 주고 있어서, 고조 주민들에게는 큰 인기다\n　시라나미는, 우리 동료가 됐지만, 아무래도, 동기는 그다지 순수하지 않은 듯하다',
    '3466e8ba8d': '　새로 나즈나가 동료가 됐다\n　나즈나는, 식신이라고 해서, 정령계라는 곳에서 오는 일종의 요정이라나 보다\n　나즈나는, 뿌리 없는 자라고 해서, 의식도 없이 이쪽으로 온 식신이다\n　본인이 몰래 알려 준 바로는, 정령계에 질려서 이쪽',
    'c0a6632879': '세상에 왔지만, 여기도 그다지 재미없어서, 동굴 안에서 스스로를 봉인하고 잠들어 있었다던가・\n　어쨌든, 아스카에게 딱 붙어 있고, 지켜보기에 매우 재밌다 하지만, 그걸 말하면 아스카가 몹시 화내니 비밀로 하자',
    '6768c2b2dd': '　새로운 동료가 또 늘었다\n　그의 이름은, 카무이 카무이코탄이라는 작은 산골 마을의 족장으로, 정령의 힘으로 곰이나 매 같은 짐승으로 변신하는 힘을 지녔다\n　유카리 씨라는 연인이 있어서, 카무이는 그녀를 매우 소중히 여긴다',
    'd0196a0b61': '　그의 마을 사람들이 카달에게 인질로 잡혀 있던 것을, 협력해서 구해 낸 것이, 카무이가 우리 동료가 된 계기였다\n　동료 중에서는 가장 상식적이라, 우리에게는, 나이 많은 형처럼 느껴진다 가끔, 그의 이야기가, 설교처럼 들리긴 해도',
    'b6381db94e': '　오보로계곡이란, 으스스한 곳이다\n끊임없이 안개인지 아지랑이인지 모를 묘한 연기가 감돌아, 우리의 침입을 막는 듯한 면이 있다\n　오보로계곡에는, 그 특이한 풍경 말고도, 하나 더, 달갑잖은 명물이 있다',
    'b739aa1baf': '　오보로계곡의 아야공주라 하면, 리그로드의 영웅들이 싸운 그 전쟁에서, 뮤와 내 선조들을 괴롭힌 상대다\n　여기에는, 그 아야공주의 피를 이은 미즈타마라는 여도적이 있었다\n　지기 싫어하는 성격인지 앞으로도 계속 우리에게 덤벼들지 모른다고 생각하니, 진저리가 난다',
    '020e85a4db': '　쿠리카라 마을에는, 포술이라는, 화약을 다루는 기술이 있다 그 일인자가 타타라라는 거한이다\n　카달군은 포술에 전략적 가치를 발견하고, 타타라 일행에게 협력을 명했다\n　하지만, 자신들의 기술이 무익한 대량살인에 쓰이는 것을 싫어한 타타라 일행은, 카달의 요구에 계속 반대했다',
    'd73de6c2ba': '　그리고, 우리가 쿠리카라 마을을 찾은 그날, 카달 무리에 의해, 마을에 불이 놓였다\n　우리는 결사의 각오로 화약창고로 향해, 대폭발이 일어나기 전에 불을 끌 수 있었다\n　이렇게, 쿠리카라에서 제일가는 솜씨를 지닌 타타라가 동료가 됐다',
    '52e2376789': '　그리고, 우리가 쿠리카라 마을을 찾은 그날, 카달 무리에 의해, 마을에 불이 놓였다\n　우리는 결사의 각오로 화약창고로 향했지만, 폭발을 막지 못했다\n　쿠리카라 마을은 폭발과 함께 날아갔고, 우리는, 힘이 부족했음을 후회했다\n　그 다정한 사람들의 미소가 돌아오는 일은 이제 없다',
    '1d82fd04b1': '　결계동은, 야마타이 중앙에 위치한 영봉 후지를 관통하는 지하동굴이다\n　이곳은 예로부터 뒷야마타이 지방과 앞야마타이 지방을 가르는 요충지로, 게텐성의 주인을 지키기 위해 한번 봉인되면 특별한 아이템을 세 개 모으지 않으면, 봉인을 풀 수 없다',
    'ee1877d9e6': '　우리는 고생 끝에, 세 아이템을 모아, 게텐성으로 향하기 위해, 결계동의 봉인을 풀었다\n　갈자드와 카달군이 거점으로 삼은 게텐성은, 이제 코앞이다',
    'a16fa4af4e': '　나는, 이 게텐이라는 성에서 일어난 일을 평생 잊지 못할 것이다・\n　우리는 카달의 장군 갈자드를 게텐성 가장 깊은 곳에서 찾아냈다 거기까지 몰아붙였다고 생각한 것은 우리의 큰 오산이었다\n　갈자드는 자신의 필요에 따라, 그 장소',
    '8a4013bd15': '로 이동했을 뿐이었고, 우리를 위협으로 여기지 않았던 것이다\n　갈자드는 갑자기 사라졌고, 그것을 막으려 한 뮤도 또한, 갈자드와 함께 사라져 버렸다\n　대체, 뮤는 어디로 가 버린 걸까・',
    '67d8c17bd7': '　항구마을 히가타에서 어찌할 바를 모르고 있는데 낯익은 얼굴을 만났다\n　리그로드에서 야마타이까지 나와 뮤를 배로 실어 준 디아네 씨였다\n　디아네 씨는, 뮤에 대해 듣더니, 카달까지 배로 데려다주겠다고 제안해 주었다',
    '3e4d9012aa': '　우리는, 디아네 씨의 호의에 기대어, 곧장, 카달을 향하게 됐다\n　뮤・부디 우리가 카달에 도착할 때까지, 무사히 있어 줘・',
    '856b55e220': '　뮤와 재회！ 이렇게 기쁜 일은 없었다 만나지 못해 불안해서, 따라붙는 불길한 생각을 몇 번이나 억눌렀던가\n　항구마을 포포론은 카달의 바다 관문 이곳은 늘 다른 대륙에서 새롭고 진귀한 문화가 밀려드는 곳이다',
    '917e94746a': '　그래서, 사람들도, 한쪽 생각에 치우치지 않는 것 같아 카달의 방식에 반대하는 움직임도 있는 듯하다\n　뮤는, 갈자드에게 붙잡혀 있던 감옥 안에서 앙주라는 새로운 동료를 만났다',
    '20c212c4db': '　７인위원회의 탑에 쳐들어간 우리는, 갈자드와 싸워, 그를 물리쳤다\n　하지만, ７인위원회는, 이미 그들의 야망을 이루기 위해 떠난 뒤였다\n　그들은, 세상의 숙정과 지배를 바라고 있었다 그러기 위해, 카카루크란으로 가서, 카오스의 힘을 이용하려는 것이다, 라고',
    'af061086bd': '　진정으로 우수한 인간에 의한 새로운 이상세계, 라고 그들은 표현하는 모양이지만, 무엇 하나 사라져 없어지고, 아무도 없는 왕국을 지배해서, 대체 무슨 의미가 있단 말인가\n　저들 ７인위원회의 행동은, 무슨 일이 있어도 막아야 한다',
    '53b0113788': '　포포론은, 그날, 현실적으로도, 상징적으로도 죽음의 거리가 되었다\n　７인위원회는, 포포론에 사는 사람들을 피로 숙정했다\n　우리는 아무것도 할 수 없었다',
    '17dc4b8f48': '　알렉트리아 대도서관의 관장실에, 비밀 입구가 있었다\n　안에 들어가 보니, 귀중한 문헌이 보관되어 있어서, 우리는 여러 가지를 알 수 있었다\n　앙주에 따르면, 거기 숨겨진 문헌은, 하나같이, 허가 없이 볼 수 없는 중요서류라고 한다',
    '6906937903': '　지하열람실에서 찾은 정보를 바탕으로, 우리는, 그래비티라는 마을을 찾아가기 위해, 알렉트리아 대도서관의 지하통로를 나아갔다',
    'ce3886c8a1': '　그래비티는, 하늘을 나는 배 익시즈에 관한 비밀을 지키기 위해, 세상 한구석에서 잊혀져 있던 마을이었다\n　이곳에는, 알렉트리아 도서관조차 잊은 지식이 살아 있었다',
    '5a694b5414': '　장로의 이야기에 따르면, 그래비티 근처에 있는 해저신전에 익시즈가 잠들어 있다는 것과, 익시즈의 원동력인 갈만오브가 ７인위원회에 의해 도둑맞았기 때문에, 익시즈를 움직이려면, 어딘가에서 갈만오브를 찾아내는 수밖에 없다는 것이다',
    '8231c4e4b5': '　우리는 죽음의 사막이라 불리는 사막을 통과했다 그곳은, 가만히 있기만 해도 체력을 잃는 무더운 사막이었다\n　죽음의 사막을 통과해, 고대 유적으로 보이는, 거대한 돌로 만든 네모난 건물을 발견했다\n　여기에는, 뭔가 있을 것 같은 예감이 든다',
    '68efde626d': '　이시스피라미드라 불리는 그 고대유적은, 갈만오브를 보관하는, 오직 그 목적만을 위해 만들어졌다고 해도 과언이 아닌 듯했다',
    '7d543696b0': '　우리는, 거기서, 갈만오브를 찾을 수 있었다\n　이걸로, 그래비티 근처에 있는 해저신전에 가면, 염원하던 익시즈 부활이다！',
    'e2dd4f8796': '　마침내 우리는, 익시즈호를 손에 넣었다！\n７인위원회가 차원의 문 봉인을 깨고 카카루크란으로 가는 것만큼은 무슨 수를 써서든 막아야 한다\n　그리운 고향 리그로드로 서두르자！',
    'a74af59f5e': '　드림라비린스에 갇혀 있던 것은 자칭 천재 마도사 킹이었다\n　킹은 반인반마인 켄타우로스 종족으로, 스스로 말하는 만큼, 마법 실력은 뛰어난 모양이다\n　하지만, 성격에는, 여러모로 문제가 있어 보이는데말이지～・',
    '3a0de9f8e5': '　드라군 상공에 접어든 익시즈호에 갑자기 변화가 일어났다\n　우리를 태운 익시즈호는 추락했고, 수리할 방도는 서 있지 않다\n　대체, 익시즈호에 무슨 일이 일어난 걸까',
    'ec5e23f3cd': '　드라군성은 카달에 의해 파괴되어 있었다\n　수많은 드라군 기사들이 돌아오지 못했고, 무용으로 이름난 드라군 왕도, 또한, 돌아오지 못했다',
    'e45e5cb192': '　처음에는, 우리를 배신자라 부르던 자루마 사람들은, 드라군성을 되찾자, 손바닥 뒤집듯 친절해졌다\n　그들을 탓할 수는 없다 무너져 내린 드라군성처럼, 자루마 사람들의 마음도, 깊이 상처 입었을 테니까',
    '081a097217': '　새로운 동료가 느는 것은, 든든한 일이라고, 나는 생각한다\n　오르트마에서 장사를 하는 매인간 호크아이는, 독학으로 검술을 연마한 별난 남자였다\n　호크아이의 도움으로, 대지의 절규를 돌파할 수 있었다',
    '6f5f2bb386': '　놀라운 것은, 알렉트리아 대도서관 지하열람실에서 본 여러 고대마법문명에 관한 문헌의 저자, 팔코의 친형이었다는 것이다\n　우리는, 익시즈호의 수복에 협력을 구하고자 호크아이와 함께, 카달에 붙잡혀 있다는 팔코를 구하러 가기로 했다',
    '86f4774543': '　라그로스는 틀림없는 악당이었다고 생각한다 하지만, 그에게도 또한, 깊은 마음의 상처가 있었던 것처럼 느껴져 견딜 수 없다\n　라그로스를 쓰러뜨림으로써, 그로 인해 잃은 내 가족의 원수를 갚을 수는 있었다\n　그렇다고 해서, 잃은 목숨이 돌아오는 건 아니다',
    '04f97f9460': '　더는, 이런 아픔을 겪는 사람들이 느는 건 사양이다\n　유현의숲을 봉인한 루나에게서 얻은 정보로, ７인위원회는 이미 차원의 문에 다다르고 있는 듯하다\n　그들의 어리석은 짓을 막아야 한다',
    '62aa28a29f': '　고대마법문명, 특히 익시즈호에 관해 학술적 흥미를 가진 팔코를, 그가 갇혀 있던 곳에서 구해 냈다\n　필시 눈물 어린 감동의 재회가 기다릴 줄 알았건만, 냉담하다고 느껴질 만큼 담담한 재회였다',
    '6def16f743': '　하지만, 그렇다고 해서, 두 사람이 재회한 것에 아무런 감동도 없다고 여기는 건 잘못일 것이다\n　나에게는, 형제도 자매도 없어서 잘 모르겠지만\n　팔코가 우리를 도와주게 되면서, 익시즈호 수복에 희망이 보이기 시작했다',
    'be0cc754b2': '　팔코의 말로는, 익시즈를 다시 한번, 하늘에 띄우려면, 특별한 아이템이 두 개 필요하다고 했다\n　하나는 애로우스톤이라 불리는 것, 또 하나는 말라카이트라 불리는 것이라고 한다',
    '8cfe23ae0b': '　그것이 어떤 원리로 효력을 잃은 갈만오브에 작용하는지는, 설명을 듣긴 했지만, 결국, 잘 모르겠다\n　어쨌든, 이 두 가지를 찾아내야 한다',
    '15bdd064b8': '　그래비티의 장로에게, 말라카이트에 관한 정보가 알렉트리아 도서관에 있지 않겠냐는 말을 들었다',
    'd38c160a24': '　사모사섬에서 익시즈호 수복에 필요한 두 아이템 중 하나, 애로우스톤을 입수\n　이걸로 한 걸음, 익시즈호 수복에 가까워진 셈이다',
    '978bc7189a': '　알렉트리아 대도서관 지하통로에서 익시즈호 수복에 필요한 두 아이템 중 하나, 말라카이트를 입수\n　이걸로 한 걸음, 익시즈호 수복에 가까워진 셈이다',
    '2362cc213b': '　팔코, 디아네의 도움으로, 익시즈호 수복이 끝났다\n　지난번 실수를 되풀이하지 않기 위해, 이번엔 아마추어가 아니라, 디아네라는 조종 전문가와 팔코라는 고대마법문명 전문가에게 맡기기로 했다',
    '7640c09c08': '　디아네도 팔코도, 이 익시즈호에 타고 있는 것만으로 행복하다는 표정을 짓고 있었다',
    '4d31cbda32': '　차원의 길을 돌파했다 카카루크란은 눈앞이다 긴장한 탓에, 더 이상 써야 할 것이 떠오르지 않는다\n　전원, 살아서 돌아간다 그것만을 가슴에 품고, ７인위원회에 싸움을 건다',
    '19e4a8d06e': '　７인위원회를 쓰러뜨렸다！・일 텐데, 뭔가 이상하다고, 내 머릿속 한구석이 걸린다\n　뮤와 함께 세상을 익시즈로 돌아보기로 한다\n　정말로 세상에 평화가 찾아왔는지, 이 눈으로 확인해 보자',
    'd16f7e2d21': '　알렉트리아 도서관장의 유서를 발견 거기에는 놀라운 사실이 적혀 있었다\n　하지만, 무엇보다도, 마법구의 출현과 천재지변에 놀랐다\n　싸움은 아직 끝나지 않았다 진정한 평화를 쟁취하기 위해, 다시 한번, 카카루크란으로 여정을 떠난다',
    '81c6530637': '　이번에야말로, 사력을 다한 싸움이 될 것이다 하지만, 그래도, 우리가 이길 거라 믿고 싶다 짓눌려, 공포에 울부짖는 사람들의 마음에, 아름다운 단 하나의 진실을, 불어넣기 위해, 우리는 싸우자\n　긍지를 빼앗는 것은 누구도 할 수 없다고, 그 한마디를 증명하기 위해',
    '4f7f5034f1': '　이상으로 일기는 끝입니다\n\ncreate: 1 Aug.96\nupdate:20 Aug.96\n\n　마스터업하면 흑맥주에 불꽃놀이다(웃음)',
    'a3e4521f9b': '순풍만범,\n\n　세상만사\n\n　　버그도 없다\n\n\n\n\n\n　　・라고 일기에는\n　　　　　써 두자',
}
